class Employee {
    public String role() { return "Employee"; }
    public static String policy() { return "standard"; }
}
class Manager extends Employee {
    @Override
    public String role() { return "Manager"; }
    public static String policy() { return "management"; }
}
public class Main {
    public static void main(String[] args) {
        Employee e = new Manager();
        System.out.println(e.role());
        System.out.println(e.policy());
        System.out.println(((Manager) e).policy());
    }
}

